const express = require('express');
const app = express();

app.use(express.json());

// ---------------------------------------------------------------------------
// Safe rule evaluation.
//
// NOTE: The reference snippet in docs/RULES_ENGINE.md evaluates caller-supplied
// rule strings via `Function(...)` (i.e. eval). That is arbitrary remote code
// execution against untrusted request input and is intentionally NOT used here.
// Instead we parse a restricted boolean expression grammar that can only read
// values from the provided context and compare/combine them. No host objects,
// no `req`, no `require`, no function calls are reachable from a rule.
//
// Supported grammar:
//   expr    := or
//   or      := and ('||' and)*
//   and      := not ('&&' not)*
//   not     := '!' not | comparison
//   comparison := primary (('=='|'!='|'>='|'<='|'>'|'<') primary)?
//   primary := number | string | true | false | null | identifierPath | '(' expr ')'
//   identifierPath := ident ('.' ident)*   // resolved against ctx only
// ---------------------------------------------------------------------------

function tokenize(input) {
  const tokens = [];
  const re = /\s*(>=|<=|==|!=|&&|\|\||[<>!()]|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|-?\d+(?:\.\d+)?|[A-Za-z_$][A-Za-z0-9_$.]*)\s*/y;
  let pos = 0;
  while (pos < input.length) {
    re.lastIndex = pos;
    const m = re.exec(input);
    if (!m || m.index !== pos) {
      throw new Error(`Unexpected token at position ${pos}`);
    }
    tokens.push(m[1]);
    pos = re.lastIndex;
  }
  return tokens;
}

function parseRule(input) {
  const tokens = tokenize(input);
  let i = 0;
  const peek = () => tokens[i];
  const next = () => tokens[i++];
  const expect = (t) => {
    if (next() !== t) throw new Error(`Expected '${t}'`);
  };

  function parseExpr() { return parseOr(); }

  function parseOr() {
    let node = parseAnd();
    while (peek() === '||') { next(); node = { op: '||', l: node, r: parseAnd() }; }
    return node;
  }
  function parseAnd() {
    let node = parseNot();
    while (peek() === '&&') { next(); node = { op: '&&', l: node, r: parseNot() }; }
    return node;
  }
  function parseNot() {
    if (peek() === '!') { next(); return { op: '!', v: parseNot() }; }
    return parseComparison();
  }
  function parseComparison() {
    const left = parsePrimary();
    const t = peek();
    if (['==', '!=', '>=', '<=', '>', '<'].includes(t)) {
      next();
      return { op: t, l: left, r: parsePrimary() };
    }
    return left;
  }
  function parsePrimary() {
    const t = next();
    if (t === undefined) throw new Error('Unexpected end of expression');
    if (t === '(') { const e = parseExpr(); expect(')'); return e; }
    if (t === 'true') return { lit: true };
    if (t === 'false') return { lit: false };
    if (t === 'null') return { lit: null };
    if (/^-?\d+(?:\.\d+)?$/.test(t)) return { lit: Number(t) };
    if (/^"(?:[^"\\]|\\.)*"$/.test(t) || /^'(?:[^'\\]|\\.)*'$/.test(t)) {
      return { lit: JSON.parse('"' + t.slice(1, -1).replace(/\\'/g, "'").replace(/"/g, '\\"') + '"') };
    }
    if (/^[A-Za-z_$][A-Za-z0-9_$.]*$/.test(t)) return { path: t.split('.') };
    throw new Error(`Unexpected token '${t}'`);
  }

  const ast = parseExpr();
  if (i !== tokens.length) throw new Error('Unexpected trailing tokens');
  return ast;
}

function resolvePath(path, ctx) {
  let cur = ctx;
  for (const key of path) {
    if (cur == null || typeof cur !== 'object' || !Object.prototype.hasOwnProperty.call(cur, key)) {
      return undefined;
    }
    cur = cur[key];
  }
  return cur;
}

function evaluate(node, ctx) {
  if ('lit' in node) return node.lit;
  if ('path' in node) {
    // First segment must be 'ctx'; only the context object is reachable.
    if (node.path[0] !== 'ctx') throw new Error('Rules may only reference ctx.*');
    return resolvePath(node.path.slice(1), ctx);
  }
  switch (node.op) {
    case '||': return evaluate(node.l, ctx) || evaluate(node.r, ctx);
    case '&&': return evaluate(node.l, ctx) && evaluate(node.r, ctx);
    case '!': return !evaluate(node.v, ctx);
    case '==': return evaluate(node.l, ctx) === evaluate(node.r, ctx);
    case '!=': return evaluate(node.l, ctx) !== evaluate(node.r, ctx);
    case '>': return evaluate(node.l, ctx) > evaluate(node.r, ctx);
    case '>=': return evaluate(node.l, ctx) >= evaluate(node.r, ctx);
    case '<': return evaluate(node.l, ctx) < evaluate(node.r, ctx);
    case '<=': return evaluate(node.l, ctx) <= evaluate(node.r, ctx);
    default: throw new Error('Unknown operator');
  }
}

