// --- Safe rule evaluator -----------------------------------------------------
// NOTE: The "reference implementation" in docs/RULES_ENGINE.md evaluates the
// caller-supplied `rule` string with Function()/eval. That is a remote code
// execution vulnerability: any client could run arbitrary code on the server.
// We deliberately do NOT use it. Instead we parse the expression into an AST
// and evaluate it against the supplied context with no access to globals,
// require(), the filesystem, or the process — only data in `ctx`.

// Tokenizer
function tokenize(src) {
  const tokens = [];
  const re = /\s*([0-9]+(?:\.[0-9]+)?|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|>=|<=|===|!==|==|!=|&&|\|\||[()<>!]|[A-Za-z_$][A-Za-z0-9_$.]*)/y;
  let m;
  let pos = 0;
  while (pos < src.length) {
    re.lastIndex = pos;
    m = re.exec(src);
    if (!m) {
      if (/\s/.test(src[pos])) { pos++; continue; }
      throw new Error(`Unexpected token at position ${pos}`);
    }
    tokens.push(m[1]);
    pos = re.lastIndex;
  }
  return tokens;
}

// Recursive-descent parser -> AST. Grammar (lowest to highest precedence):
// or -> and ('||' and)*
// and -> cmp ('&&' cmp)*
// cmp -> unary (('=='|'!='|'==='|'!=='|'<'|'>'|'<='|'>=') unary)?
// unary -> '!' unary | primary
// primary -> number | string | 'true'|'false'|'null' | identifier-path | '(' or ')'
function parse(tokens) {
  let i = 0;
  const peek = () => tokens[i];
  const next = () => tokens[i++];
  const expect = (t) => {
    if (tokens[i] !== t) throw new Error(`Expected '${t}'`);
    i++;
  };

  function parseOr() {
    let left = parseAnd();
    while (peek() === '||') { next(); left = { type: 'logical', op: '||', left, right: parseAnd() }; }
    return left;
  }
  function parseAnd() {
    let left = parseCmp();
    while (peek() === '&&') { next(); left = { type: 'logical', op: '&&', left, right: parseCmp() }; }
    return left;
  }
  function parseCmp() {
    let left = parseUnary();
    const ops = ['==', '!=', '===', '!==', '<', '>', '<=', '>='];
    if (ops.includes(peek())) {
      const op = next();
      left = { type: 'binary', op, left, right: parseUnary() };
    }
    return left;
  }
  function parseUnary() {
    if (peek() === '!') { next(); return { type: 'not', arg: parseUnary() }; }
    return parsePrimary();
  }
  function parsePrimary() {
    const t = peek();
    if (t === undefined) throw new Error('Unexpected end of expression');
    if (t === '(') { next(); const e = parseOr(); expect(')'); return e; }
    if (/^[0-9]/.test(t)) { next(); return { type: 'literal', value: Number(t) }; }
    if (t[0] === '"' || t[0] === "'") { next(); return { type: 'literal', value: JSON.parse('"' + t.slice(1, -1).replace(/\\?(["'])/g, '\\$1') + '"') }; }
    if (t === 'true') { next(); return { type: 'literal', value: true }; }
    if (t === 'false') { next(); return { type: 'literal', value: false }; }
    if (t === 'null') { next(); return { type: 'literal', value: null }; }
    if (/^[A-Za-z_$]/.test(t)) { next(); return { type: 'path', path: t.split('.') }; }
    throw new Error(`Unexpected token '${t}'`);
  }

  const ast = parseOr();
  if (i !== tokens.length) throw new Error(`Unexpected token '${tokens[i]}'`);
  return ast;
}

// Safe property lookup: only own enumerable data props, blocks prototype access.
const BLOCKED = new Set(['__proto__', 'prototype', 'constructor']);
function resolvePath(path, scope) {
  let cur = scope;
  for (const key of path) {
    if (cur == null) return undefined;
    if (BLOCKED.has(key)) throw new Error(`Access to '${key}' is not allowed`);
    if (typeof cur !== 'object') return undefined;
    cur = Object.prototype.hasOwnProperty.call(cur, key) ? cur[key] : undefined;
  }
  return cur;
}

function evaluate(node, scope) {
  switch (node.type) {
    case 'literal': return node.value;
    case 'path': return resolvePath(node.path, scope);
    case 'not': return !evaluate(node.arg, scope);
    case 'logical': {
      const l = evaluate(node.left, scope);
      if (node.op === '&&') return l && evaluate(node.right, scope);
      return l || evaluate(node.right, scope);
    }
    case 'binary': {
      const l = evaluate(node.left, scope);
      const r = evaluate(node.right, scope);
      switch (node.op) {
        case '==': return l == r; // eslint-disable-line eqeqeq
        case '!=': return l != r; // eslint-disable-line eqeqeq
        case '===': return l === r;
        case '!==': return l !== r;
        case '<': return l < r;
        case '>': return l > r;
        case '<=': return l <= r;
        case '>=': return l >= r;
      }
    }
    /* istanbul ignore next */
    default: throw new Error('Unknown node type');
  }
}

// Evaluate a caller-supplied rule expression against the request context.
// Only `ctx` (the supplied data) is exposed — no req, globals, or require().
function evalRule(expr, context) {
  if (typeof expr !== 'string') throw new Error('rule must be a string');
  if (expr.length > 1000) throw new Error('rule too long');
  const ast = parse(tokenize(expr));
  return Boolean(evaluate(ast, { ctx: context ?? {} }));
}

app.post('/check', (req, res) => {
  const { rule, context } = req.body || {};
  if (typeof rule !== 'string') {
    return res.status(400).json({ error: "Missing or invalid 'rule' (expected a string)" });
  }
  try {
    const result = evalRule(rule, context);
    res.json({ result, rule });
  } catch (err) {
    res.status(400).json({ error: `Invalid rule: ${err.message}` });
  }
});

