// documented use case (comparisons / boolean logic over the context object)
// with no access to globals, require, process, or arbitrary code.
// ---------------------------------------------------------------------------

// Tokenize a restricted expression grammar.
function tokenize(expr) {
  const tokens = [];
  const re =
    /\s*(?:(>=|<=|==|!=|&&|\|\||[<>()!])|("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')|(-?\d+(?:\.\d+)?)|(true|false|null)|([A-Za-z_$][A-Za-z0-9_$.]*))/y;
  let i = 0;
  while (i < expr.length) {
    re.lastIndex = i;
    const m = re.exec(expr);
    if (!m || m.index !== i) {
      // allow trailing whitespace
      if (expr.slice(i).trim() === '') break;
      throw new Error(`Unexpected token near: ${expr.slice(i)}`);
    }
    i = re.lastIndex;
    if (m[1]) tokens.push({ type: 'op', value: m[1] });
    else if (m[2]) tokens.push({ type: 'lit', value: m[2].slice(1, -1) });
    else if (m[3]) tokens.push({ type: 'lit', value: Number(m[3]) });
    else if (m[4])
      tokens.push({
        type: 'lit',
        value: m[4] === 'true' ? true : m[4] === 'false' ? false : null,
      });
    else if (m[5]) tokens.push({ type: 'ident', value: m[5] });
  }
  return tokens;
}

// Recursive-descent parser -> AST. Grammar (lowest to highest precedence):
//   or  := and ('||' and)*
//   and := cmp ('&&' cmp)*
//   cmp := unary (('>'|'<'|'>='|'<='|'=='|'!=') unary)?
//   unary := '!' unary | primary
//   primary := literal | ident | '(' or ')'
function parse(tokens) {
  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];

  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().value === '||') {
      next();
      left = { kind: 'logic', op: '||', left, right: parseAnd() };
    }
    return left;
  }
  function parseAnd() {
    let left = parseCmp();
    while (peek() && peek().value === '&&') {
      next();
      left = { kind: 'logic', op: '&&', left, right: parseCmp() };
    }
    return left;
  }
