// safeRule.js
//
// Safe evaluator for caller-supplied rule expressions.
//
// SECURITY NOTE:
// The reference implementation in docs/RULES_ENGINE.md evaluates the
// caller-supplied `rule` string with `Function(...)` (i.e. eval). Because the
// rule comes from the untrusted request body, that approach is a critical
// Remote Code Execution vulnerability: a client could run arbitrary Node code
// (read files, spawn processes, exfiltrate secrets, etc.).
//
// This module implements the same *feature* — evaluating a boolean/arithmetic
// rule against a request context — using a small, dependency-free recursive
// descent parser. The supported grammar is intentionally limited:
//
//   - literals: numbers, single/double quoted strings, true, false, null
//   - identifier `ctx` and dotted/bracketed property access (ctx.amount, ctx["a"])
//   - arithmetic: + - * / %
//   - comparison: > >= < <= == != === !==
//   - logical: && || !
//   - parentheses for grouping
//
// There are NO function calls, NO arbitrary identifiers, and NO access to
// globals, `require`, `process`, prototypes, etc. Property access is performed
// with own-property checks only, so prototype-pollution / gadget lookups
// (e.g. constructor, __proto__) are rejected.

const FORBIDDEN_KEYS = new Set([
  '__proto__',
  'prototype',
  'constructor',
]);

// ---- Tokenizer ----------------------------------------------------------

function tokenize(input) {
  const tokens = [];
  let i = 0;
  const n = input.length;

  const isIdentStart = (c) => /[A-Za-z_$]/.test(c);
  const isIdentPart = (c) => /[A-Za-z0-9_$]/.test(c);
  const isDigit = (c) => /[0-9]/.test(c);

  while (i < n) {
    const c = input[i];

    if (c === ' ' || c === '\t' || c === '\n' || c === '\r') {
      i++;
      continue;
    }

    // String literal
    if (c === '"' || c === "'") {
      const quote = c;
      let str = '';
      i++;
      while (i < n && input[i] !== quote) {
        if (input[i] === '\\') {
          const next = input[i + 1];
          if (next === undefined) throw new SyntaxError('Unterminated escape');
          const map = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', "'": "'" };
          str += map[next] !== undefined ? map[next] : next;
          i += 2;
        } else {
          str += input[i];
          i++;
        }
      }
      if (i >= n) throw new SyntaxError('Unterminated string literal');
      i++; // closing quote
      tokens.push({ type: 'string', value: str });
      continue;
    }

    // Number literal
    if (isDigit(c) || (c === '.' && isDigit(input[i + 1]))) {
      let num = '';
      while (i < n && (isDigit(input[i]) || input[i] === '.')) {
        num += input[i];
        i++;
      }
      if ((num.match(/\./g) || []).length > 1) {
        throw new SyntaxError('Invalid number: ' + num);
      }
      tokens.push({ type: 'number', value: parseFloat(num) });
      continue;
    }

    // Identifier / keyword
    if (isIdentStart(c)) {
      let id = '';
      while (i < n && isIdentPart(input[i])) {
        id += input[i];
        i++;
      }
      if (id === 'true') tokens.push({ type: 'boolean', value: true });
      else if (id === 'false') tokens.push({ type: 'boolean', value: false });
      else if (id === 'null') tokens.push({ type: 'null', value: null });
      else tokens.push({ type: 'ident', value: id });
      continue;
    }

    // Multi-char operators
    const three = input.slice(i, i + 3);
    if (three === '===' || three === '!==') {
      tokens.push({ type: 'op', value: three });
      i += 3;
      continue;
    }
    const two = input.slice(i, i + 2);
    if (['==', '!=', '>=', '<=', '&&', '||'].includes(two)) {
      tokens.push({ type: 'op', value: two });
      i += 2;
      continue;
    }

    // Single-char tokens
    if ('+-*/%<>!()[].'.includes(c)) {
      tokens.push({ type: 'op', value: c });
      i++;
      continue;
    }

    throw new SyntaxError('Unexpected character: ' + c);
  }

  tokens.push({ type: 'eof' });
  return tokens;
}

// ---- Parser (recursive descent) ----------------------------------------
// Precedence (low -> high):
//   ||  >  &&  >  equality  >  comparison  >  additive  >  multiplicative
//   >  unary (! -)  >  postfix (member access)  >  primary

function parse(tokens) {
  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];
  const expectOp = (v) => {
    const t = next();
    if (t.type !== 'op' || t.value !== v) {
      throw new SyntaxError('Expected "' + v + '"');
    }
  };

  function parseExpression() {
    return parseLogicalOr();
  }

  function parseLogicalOr() {
    let left = parseLogicalAnd();
    while (peek().type === 'op' && peek().value === '||') {
      next();
      left = { kind: 'logical', op: '||', left, right: parseLogicalAnd() };
    }
    return left;
  }

  function parseLogicalAnd() {
    let left = parseEquality();
    while (peek().type === 'op' && peek().value === '&&') {
      next();
      left = { kind: 'logical', op: '&&', left, right: parseEquality() };
    }
    return left;
  }

  function parseEquality() {
    let left = parseComparison();
    while (peek().type === 'op' && ['==', '!=', '===', '!=='].includes(peek().value)) {
      const op = next().value;
      left = { kind: 'binary', op, left, right: parseComparison() };
    }
    return left;
  }

  function parseComparison() {
    let left = parseAdditive();
    while (peek().type === 'op' && ['>', '>=', '<', '<='].includes(peek().value)) {
      const op = next().value;
      left = { kind: 'binary', op, left, right: parseAdditive() };
    }
    return left;
  }

  function parseAdditive() {
    let left = parseMultiplicative();
    while (peek().type === 'op' && ['+', '-'].includes(peek().value)) {
      const op = next().value;
      left = { kind: 'binary', op, left, right: parseMultiplicative() };
    }
    return left;
  }

  function parseMultiplicative() {
    let left = parseUnary();
    while (peek().type === 'op' && ['*', '/', '%'].includes(peek().value)) {
      const op = next().value;
      left = { kind: 'binary', op, left, right: parseUnary() };
    }
    return left;
  }

  function parseUnary() {
    if (peek().type === 'op' && (peek().value === '!' || peek().value === '-')) {
      const op = next().value;
      return { kind: 'unary', op, arg: parseUnary() };
    }
    return parsePostfix();
  }

  function parsePostfix() {
    let node = parsePrimary();
    while (peek().type === 'op' && (peek().value === '.' || peek().value === '[')) {
      if (peek().value === '.') {
        next();
        const prop = next();
        if (prop.type !== 'ident') throw new SyntaxError('Expected property name after "."');
        node = { kind: 'member', object: node, property: { kind: 'literal', value: prop.value } };
      } else {
        next(); // [
        const propExpr = parseExpression();
        expectOp(']');
        node = { kind: 'member', object: node, property: propExpr, computed: true };
      }
    }
    return node;
  }

  function parsePrimary() {
    const t = peek();
    if (t.type === 'number' || t.type === 'string' || t.type === 'boolean' || t.type === 'null') {
      next();
      return { kind: 'literal', value: t.value };
    }
    if (t.type === 'ident') {
      next();
      // Only the context root identifiers are allowed.
      if (t.value !== 'ctx') {
        throw new SyntaxError('Unknown identifier: ' + t.value + ' (only "ctx" is allowed)');
      }
      return { kind: 'context' };
    }
    if (t.type === 'op' && t.value === '(') {
      next();
      const expr = parseExpression();
      expectOp(')');
      return expr;
    }
    throw new SyntaxError('Unexpected token: ' + JSON.stringify(t));
  }

  const ast = parseExpression();
  if (peek().type !== 'eof') {
    throw new SyntaxError('Unexpected trailing tokens');
  }
  return ast;
}

// ---- Evaluator ----------------------------------------------------------

function evaluate(node, ctx) {
  switch (node.kind) {
    case 'literal':
      return node.value;
    case 'context':
      return ctx;
    case 'member': {
      const obj = evaluate(node.object, ctx);
      if (obj === null || obj === undefined) return undefined;
      const key = node.computed ? evaluate(node.property, ctx) : node.property.value;
      const keyStr = String(key);
      if (FORBIDDEN_KEYS.has(keyStr)) {
        throw new Error('Access to "' + keyStr + '" is not allowed');
      }
      // Only allow own enumerable properties — no prototype-chain lookups.
      if (typeof obj !== 'object') return undefined;
      if (!Object.prototype.hasOwnProperty.call(obj, keyStr)) return undefined;
      const value = obj[keyStr];
      if (typeof value === 'function') {
        throw new Error('Accessing functions is not allowed');
      }
      return value;
    }
    case 'unary': {
      const v = evaluate(node.arg, ctx);
      if (node.op === '!') return !v;
      if (node.op === '-') return -v;
      throw new Error('Unknown unary op: ' + node.op);
    }
    case 'logical': {
      const l = evaluate(node.left, ctx);
      if (node.op === '&&') return l && evaluate(node.right, ctx);
      if (node.op === '||') return l || evaluate(node.right, ctx);
      throw new Error('Unknown logical op: ' + node.op);
    }
    case 'binary': {
      const l = evaluate(node.left, ctx);
      const r = evaluate(node.right, ctx);
      switch (node.op) {
        case '+': return l + r;
        case '-': return l - r;
        case '*': return l * r;
        case '/': return l / r;
        case '%': return l % r;
        case '>': return l > r;
        case '>=': return l >= r;
        case '<': return l < r;
        case '<=': return l <= r;
        case '==': return l == r; // eslint-disable-line eqeqeq
        case '!=': return l != r; // eslint-disable-line eqeqeq
        case '===': return l === r;
        case '!==': return l !== r;
        default: throw new Error('Unknown binary op: ' + node.op);
      }
    }
    default:
      throw new Error('Unknown node kind: ' + node.kind);
  }
}

/**
 * Safely evaluate a rule expression against a context object.
 * @param {string} expr  e.g. 'ctx.amount > 100 && ctx.country == "US"'
 * @param {object} context  the request context
 * @returns {*} the result of the expression
 * @throws {SyntaxError|Error} on invalid or disallowed expressions
 */
function evalRuleSafe(expr, context) {
  if (typeof expr !== 'string') {
    throw new TypeError('rule must be a string');
  }
  if (expr.length > 1000) {
    throw new RangeError('rule expression too long');
  }
  const tokens = tokenize(expr);
  const ast = parse(tokens);
  return evaluate(ast, context || {});
}

module.exports = { evalRuleSafe };

