// Safe rule expression evaluator.
//
// IMPORTANT: This intentionally does NOT use eval()/new Function() on
// caller-supplied input. Evaluating attacker-controlled strings as JS is a
// remote-code-execution vulnerability. Instead we parse the expression into a
// small AST and interpret only a whitelisted set of operations against the
// provided context.
//
// Supported grammar (sufficient for rules like `ctx.amount > 100`):
//   expr        := orExpr
//   orExpr      := andExpr ( ('||') andExpr )*
//   andExpr     := notExpr ( ('&&') notExpr )*
//   notExpr     := '!' notExpr | comparison
//   comparison  := additive ( ('=='|'!='|'==='|'!=='|'<'|'<='|'>'|'>=') additive )?
//   additive    := multiplicative ( ('+'|'-') multiplicative )*
//   multiplicative := unary ( ('*'|'/'|'%') unary )*
//   unary       := '-' unary | primary
//   primary     := number | string | boolean | null | identifier-path | '(' expr ')'
//   identifier-path := IDENT ( '.' IDENT | '[' expr ']' )*
//
// No function calls, no assignment, no access to globals/prototypes.

const TOKEN = /\s*(===|!==|==|!=|<=|>=|&&|\|\||[<>+\-*/%!()[\].]|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\d+(?:\.\d+)?|[A-Za-z_$][A-Za-z0-9_$]*)/y;

function tokenize(input) {
  const tokens = [];
  let pos = 0;
  while (pos < input.length) {
    TOKEN.lastIndex = pos;
    const m = TOKEN.exec(input);
    if (!m || m.index !== pos) {
      // Skip leading whitespace handled by regex; if nothing matched, it's invalid.
      const rest = input.slice(pos).trim();
      if (rest === '') break;
      throw new Error(`Unexpected token near: ${rest.slice(0, 20)}`);
    }
    pos = TOKEN.lastIndex;
    const raw = m[1];
    tokens.push(raw);
  }
  return tokens;
}

function parse(tokens) {
  let i = 0;
  const peek = () => tokens[i];
  const next = () => tokens[i++];
  const expect = (t) => {
    if (tokens[i] !== t) throw new Error(`Expected '${t}' but got '${tokens[i] ?? 'EOF'}'`);
    i++;
  };

  function parseExpr() { return parseOr(); }

  function parseOr() {
    let node = parseAnd();
    while (peek() === '||') { next(); node = { type: 'logical', op: '||', left: node, right: parseAnd() }; }
    return node;
  }

  function parseAnd() {
    let node = parseNot();
    while (peek() === '&&') { next(); node = { type: 'logical', op: '&&', left: node, right: parseNot() }; }
    return node;
  }

  function parseNot() {
    if (peek() === '!') { next(); return { type: 'unary', op: '!', arg: parseNot() }; }
    return parseComparison();
  }

  function parseComparison() {
    let node = parseAdditive();
    const op = peek();
    if (['==', '!=', '===', '!==', '<', '<=', '>', '>='].includes(op)) {
      next();
      node = { type: 'binary', op, left: node, right: parseAdditive() };
    }
    return node;
  }

  function parseAdditive() {
    let node = parseMultiplicative();
    while (peek() === '+' || peek() === '-') {
      const op = next();
      node = { type: 'binary', op, left: node, right: parseMultiplicative() };
    }
    return node;
  }

  function parseMultiplicative() {
    let node = parseUnary();
    while (peek() === '*' || peek() === '/' || peek() === '%') {
      const op = next();
      node = { type: 'binary', op, left: node, right: parseUnary() };
    }
    return node;
  }

  function parseUnary() {
    if (peek() === '-') { next(); return { type: 'unary', op: '-', arg: parseUnary() }; }
    return parsePrimary();
  }

  function parsePrimary() {
    const t = peek();
    if (t === undefined) throw new Error('Unexpected end of expression');

    if (t === '(') {
      next();
      const node = parseExpr();
      expect(')');
      return node;
    }

    // string literal
    if (t[0] === '"' || t[0] === "'") {
      next();
      return { type: 'literal', value: JSON.parse(t[0] === "'" ? `"${t.slice(1, -1).replace(/"/g, '\\"')}"` : t) };
    }

    // number literal
    if (/^\d/.test(t)) { next(); return { type: 'literal', value: Number(t) }; }

    // keywords
    if (t === 'true') { next(); return { type: 'literal', value: true }; }
    if (t === 'false') { next(); return { type: 'literal', value: false }; }
    if (t === 'null') { next(); return { type: 'literal', value: null }; }

    // identifier path
    if (/^[A-Za-z_$]/.test(t)) {
      next();
      let node = { type: 'identifier', name: t };
      while (peek() === '.' || peek() === '[') {
        if (peek() === '.') {
          next();
          const prop = next();
          if (prop === undefined || !/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(prop)) {
            throw new Error(`Invalid property access: '${prop}'`);
          }
          node = { type: 'member', object: node, property: { type: 'literal', value: prop } };
        } else {
          next();
          const prop = parseExpr();
          expect(']');
          node = { type: 'member', object: node, property: prop };
        }
      }
      return node;
    }

    throw new Error(`Unexpected token: '${t}'`);
  }

  const ast = parseExpr();
  if (i !== tokens.length) throw new Error(`Unexpected trailing token: '${tokens[i]}'`);
  return ast;
}

// Block access to dangerous keys to prevent prototype pollution / escapes.
const BLOCKED_KEYS = new Set(['__proto__', 'prototype', 'constructor']);

function evaluate(node, scope) {
  switch (node.type) {
    case 'literal':
      return node.value;

    case 'identifier':
      if (BLOCKED_KEYS.has(node.name)) throw new Error(`Access to '${node.name}' is not allowed`);
      if (!(node.name in scope)) return undefined;
      return scope[node.name];

    case 'member': {
      const obj = evaluate(node.object, scope);
      if (obj === null || obj === undefined) return undefined;
      const key = String(evaluate(node.property, scope));
      if (BLOCKED_KEYS.has(key)) throw new Error(`Access to '${key}' is not allowed`);
      // Only allow own enumerable-ish data access, not inherited functions.
      if (typeof obj !== 'object' && typeof obj !== 'string') return undefined;
      const val = obj[key];
      if (typeof val === 'function') throw new Error('Function access is not allowed');
      return val;
    }

    case 'unary': {
      const v = evaluate(node.arg, scope);
      if (node.op === '!') return !v;
      if (node.op === '-') return -v;
      throw new Error(`Unknown unary operator ${node.op}`);
    }

    case 'logical': {
      const l = evaluate(node.left, scope);
      if (node.op === '&&') return l && evaluate(node.right, scope);
      if (node.op === '||') return l || evaluate(node.right, scope);
      throw new Error(`Unknown logical operator ${node.op}`);
    }

    case 'binary': {
      const l = evaluate(node.left, scope);
      const r = evaluate(node.right, scope);
      switch (node.op) {
        case '+': return l + r;
        case '-': return l - r;
        case '*': return l * r;
        case '/': return l / r;
        case '%': return l % r;
        case '==': return l == r; // eslint-disable-line eqeqeq
        case '!=': return l != r; // eslint-disable-line eqeqeq
        case '===': return l === r;
        case '!==': return l !== r;
        case '<': return l < r;
        case '<=': return l <= r;
        case '>': return l > r;
        case '>=': return l >= r;
        default: throw new Error(`Unknown operator ${node.op}`);
      }
    }

    default:
      throw new Error(`Unknown node type ${node.type}`);
  }
}

/**
 * Safely evaluate a rule expression against a context object.
 * @param {string} expr   e.g. "ctx.amount > 100 && ctx.country === 'US'"
 * @param {object} context  the data the expression is evaluated against
 * @returns {*} the result of the expression
 */
function evaluateRule(expr, context) {
  if (typeof expr !== 'string') throw new Error('rule must be a string');
  if (expr.length > 1000) throw new Error('rule expression too long');
  const tokens = tokenize(expr);
  const ast = parse(tokens);
  // Expose only `ctx` to the expression. No req, no globals, no functions.
  const scope = Object.create(null);
  scope.ctx = context ?? {};
  return evaluate(ast, scope);
}

module.exports = { evaluateRule };

