//   add     := mul ( ('+'|'-') mul )*
//   mul     := unary ( ('*'|'/'|'%') unary )*
//   unary   := '!' unary | '-' unary | primary
//   primary := number | string | true | false | null
//            | path | '(' or ')'
//   path    := ident ( '.' ident | '[' or ']' )*

function tokenize(src) {
