  while (i < src.length) {
    re.lastIndex = i;
    m = re.exec(src);
    if (!m) throw new Error(`Unexpected token at position ${i}`);
    i = re.lastIndex;
    if (m[0].trim() === '') continue; // whitespace
    if (m[1] !== undefined) tokens.push({ type: 'num', value: Number(m[1]) });
    else if (m[2] !== undefined)
      tokens.push({ type: 'str', value: JSON.parse(m[2].replace(/^'|'$/g, '"')) });
    else if (m[3] !== undefined) tokens.push({ type: 'op', value: m[3] });
    else if (m[4] !== undefined) {
      const w = m[4];
      if (w === 'true') tokens.push({ type: 'lit', value: true });
      else if (w === 'false') tokens.push({ type: 'lit', value: false });
