const express = require('express');
const { compileRule } = require('./ruleEngine');

const app = express();
app.use(express.json());

// POST /check
// Body: { "rule": "ctx.amount > 100", "context": { "amount": 150 } }
// Evaluates the rule expression against the provided context and returns
// whether it passed.
//
// NOTE: The rule is evaluated by a sandboxed expression parser (ruleEngine.js),
// NOT by eval()/new Function(). Evaluating caller-supplied strings as JS would
// be a remote-code-execution vulnerability. See ruleEngine.js for details.
app.post('/check', (req, res) => {
  const { rule, context } = req.body || {};

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res
      .status(400)
      .json({ error: "Missing or invalid 'rule' (expected a non-empty string)" });
  }

  let evaluator;
  try {
    evaluator = compileRule(rule);
  } catch (err) {
    return res.status(400).json({ error: `Invalid rule expression: ${err.message}` });
  }

  try {
    const passed = evaluator(context);
    return res.json({ passed, rule, context: context ?? null });
  } catch (err) {
    return res.status(400).json({ error: `Rule evaluation failed: ${err.message}` });
  }
});

