const express = require('express');
const app = express();

app.use(express.json());

// Safe rule evaluator.
//
// NOTE: The reference snippet in docs/RULES_ENGINE.md uses
// `Function(...)` to eval a caller-supplied string. That is arbitrary
// remote code execution (CWE-94) and is intentionally NOT used here.
// Instead we evaluate a structured, allow-listed rule against the
// context. Supported rule shape:
//   { field: "amount", op: ">", value: 100 }
// with op one of: ==, !=, >, >=, <, <=, in
const ALLOWED_OPS = {
  '==': (a, b) => a === b,
  '!=': (a, b) => a !== b,
  '>': (a, b) => a > b,
  '>=': (a, b) => a >= b,
  '<': (a, b) => a < b,
  '<=': (a, b) => a <= b,
  in: (a, b) => Array.isArray(b) && b.includes(a),
};

// Resolve a dot-path like "user.role" against the context object only.
// Rejects prototype-pollution / traversal keys.
function resolvePath(ctx, path) {
  if (typeof path !== 'string') return undefined;
  const parts = path.split('.');
  let cur = ctx;
  for (const key of parts) {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      return undefined;
    }
    if (cur == null || typeof cur !== 'object') return undefined;
    cur = cur[key];
  }
  return cur;
}

function evalRule(rule, context) {
  if (!rule || typeof rule !== 'object') {
    throw new Error('rule must be an object');
  }
  const { field, op, value } = rule;
  const fn = ALLOWED_OPS[op];
  if (!fn) {
    throw new Error(`unsupported operator: ${op}`);
  }
  const actual = resolvePath(context || {}, field);
  return Boolean(fn(actual, value));
}

app.post('/check', (req, res) => {
  try {
    const { rule, context } = req.body || {};
    const result = evalRule(rule, context);
    res.json({ result });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
